from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    g=[row[:] for row in grid]
    def edge_runs(coords):
        # coords is values along boundary in order
        i=0; runs=[]
        while i<len(coords):
            if coords[i]==bg:
                i+=1; continue
            col=coords[i]; j=i+1
            while j<len(coords) and coords[j]==col: j+=1
            runs.append((i,j,col))
            i=j
        return runs
    choices=[]
    # top/bottom edge horizontal lines
    tr=edge_runs(grid[0]); br=edge_runs(grid[-1])
    for a in tr:
        for b in br:
            if a[2]==b[2]: choices.append(('h',a,b))
    # left/right edge vertical lines
    lr=edge_runs([grid[r][0] for r in range(h)])
    rr=edge_runs([grid[r][-1] for r in range(h)])
    for a in lr:
        for b in rr:
            if a[2]==b[2]: choices.append(('v',a,b))
    if not choices: return g
    # favor paired runs with greatest total extent, their marker-color points determine offsets
    orient,a,b=max(choices,key=lambda x:(min(x[1][1]-x[1][0],x[2][1]-x[2][0]), (x[1][1]-x[1][0])+(x[2][1]-x[2][0])))
    linecolor=a[2]
    points=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg and grid[r][c]!=linecolor:
                points.append((r,c,grid[r][c]))
    if not points: return g
    mc=Counter(p[2] for p in points).most_common(1)[0][0]
    points=[p for p in points if p[2]==mc]
    positions=[(c if orient=='h' else r) for r,c,_ in points]
    # determine which run contains most marker coordinates; use that run's local offsets
    ra=a[1]-a[0]; rb=b[1]-b[0]
    ca=sum(a[0]<=x<a[1] for x in positions)
    cb=sum(b[0]<=x<b[1] for x in positions)
    base=a if ca>=cb else b
    offsets={x-base[0] for x in positions if base[0]<=x<base[1]}
    if not offsets:
        return g
    # Paint inward from each opposing boundary segment along selected corresponding slots.
    if orient=='h':
        for run,from_top in ((a,True),(b,False)):
            edge=0 if from_top else h-1
            for off in offsets:
                c=run[0]+off
                if c>=run[1]: continue
                step=1 if from_top else -1
                r=edge+step
                while 0<=r<h:
                    if g[r][c]==mc:
                        g[r][c]=4
                        break
                    if g[r][c]==bg:
                        g[r][c]=mc
                    r+=step
    else:
        for run,from_left in ((a,True),(b,False)):
            edge=0 if from_left else w-1
            for off in offsets:
                r=run[0]+off
                if r>=run[1]: continue
                step=1 if from_left else -1
                c=edge+step
                while 0<=c<w:
                    if g[r][c]==mc:
                        g[r][c]=4
                        break
                    if g[r][c]==bg:
                        g[r][c]=mc
                    c+=step
    return g
